// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {HSKPredictMarket} from "./HSKPredictMarket.sol";
import {Position} from "./Position.sol";
import {HSKPredictGov} from "./HSKPredictGov.sol";

/// @title HSKPredictFactory
/// @notice Registry + factory for HSKPredict markets. Solidity port of the Sui
///         Move shared `Registry` object and the `create_market` entry point
///         (`market.move`).
///
///      On Sui, `market::init` creates a shared `Registry` at publish and
///      `create_market<T>` shares a fresh `Market<T>` object, bumping the
///      registry's `market_count` and recording `market_id → object id`. On EVM
///      there is no `init`/publish hook, so this factory is deployed once and, in
///      its constructor, deploys the single shared `Position` ERC-721 (mirroring
///      `position_market::init`). Every market is a plain `new HSKPredictMarket`
///      (no EIP-1167 clones needed for the hackathon), authorized once as the sole
///      minter/burner of its positions.
///
///      Market creation is **permissionless** — matching the Move
///      `create_market`, anyone may spin up a market; the caller becomes its owner.
contract HSKPredictFactory {
    /// @notice The single shared `Position` ERC-721, deployed by this factory.
    Position public immutable positionNFT;

    /// @notice The shared `HSKPredictGov` (HGOV) stake token for Phase 4B DAO
    ///         settlement, deployed by this factory. Markets read it via
    ///         `IProtocolRegistry(factory).govToken()`.
    address public immutable govToken;

    /// @notice Number of markets created (also the id assigned to the next market).
    ///         Mirrors the Move registry `market_count`.
    uint256 public marketCount;

    /// @notice marketId → deployed `HSKPredictMarket` address. Move `get_market`.
    mapping(uint256 => address) public markets;

    /// @notice Reverse lookup: is this address a market created by this factory?
    mapping(address => bool) public isMarket;

    /// @notice Factory admin — may rotate the protocol resolver (and itself).
    ///         Set to the deployer.
    address public admin;

    /// @notice The trusted protocol keeper authorized to settle feed-bound markets
    ///         (Phase 4A). Every `HSKPredictMarket` reads this value dynamically when
    ///         gating `resolveWithChainlink`, so rotating it here covers all existing
    ///         markets at once. This is what makes on-chain resolution keeper-only —
    ///         no arbitrary caller can trigger settlement.
    address public resolver;

    /// @notice Emitted on every market creation. Same name/fields as the Move
    ///         `MarketCreated` event so indexers stay chain-agnostic.
    event MarketCreated(uint256 indexed marketId, address market, string title);
    event ResolverUpdated(address indexed previousResolver, address indexed newResolver);
    event AdminUpdated(address indexed previousAdmin, address indexed newAdmin);

    error NotAdmin();
    error ZeroAddress();

    /// @param _resolver The trusted keeper that may call `resolveWithChainlink` on
    ///        every market created by this factory (the backend `ORACLE_SIGNER_KEY`
    ///        address). Rotatable later via `setResolver`.
    constructor(address _resolver) {
        if (_resolver == address(0)) revert ZeroAddress();
        admin = msg.sender;
        resolver = _resolver;
        // Mirrors `position_market::init`: the factory owns/authorizes the one
        // shared Position contract.
        positionNFT = new Position(address(this));
        // Phase 4B: the one shared governance/stake token for DAO settlement.
        govToken = address(new HSKPredictGov());
    }

    modifier onlyAdmin() {
        if (msg.sender != admin) revert NotAdmin();
        _;
    }

    /// @notice Rotate the protocol keeper. Admin-only. Applies to every market
    ///         (markets read `factory.resolver()` at resolution time).
    function setResolver(address newResolver) external onlyAdmin {
        if (newResolver == address(0)) revert ZeroAddress();
        emit ResolverUpdated(resolver, newResolver);
        resolver = newResolver;
    }

    /// @notice Transfer factory admin (single-step). Admin-only.
    function setAdmin(address newAdmin) external onlyAdmin {
        if (newAdmin == address(0)) revert ZeroAddress();
        emit AdminUpdated(admin, newAdmin);
        admin = newAdmin;
    }

    /// @notice Create a new market. Permissionless; `msg.sender` becomes the owner.
    /// @param collateralToken 6-decimal ERC-20 collateral (USDC).
    /// @param title Human-readable market title.
    /// @param sigmaMinMag σ floor (WAD, non-negative magnitude).
    /// @param resolvesAt Scheduled close (unix seconds, must be > 0).
    /// @param chainlinkPriceFeed Chainlink feed, or `address(0)` for a manual market.
    /// @return market The deployed `HSKPredictMarket` address.
    function createMarket(
        address collateralToken,
        string calldata title,
        int256 sigmaMinMag,
        uint256 resolvesAt,
        address chainlinkPriceFeed
    ) external returns (address market) {
        uint256 id = marketCount++;
        market = address(
            new HSKPredictMarket(
                msg.sender, // owner = creator
                collateralToken,
                address(positionNFT),
                title,
                sigmaMinMag,
                resolvesAt,
                chainlinkPriceFeed,
                id
            )
        );
        markets[id] = market;
        isMarket[market] = true;
        positionNFT.authorizeMarket(market);
        emit MarketCreated(id, market, title);
    }

    // ── Registry views (Move `market_count` / `get_market` / `market_exists`) ──

    /// @notice Get a market address by id (Move `get_market`).
    function getMarket(uint256 marketId) external view returns (address) {
        return markets[marketId];
    }

    /// @notice Whether a market id has been created (Move `market_exists`).
    function marketExists(uint256 marketId) external view returns (bool) {
        return markets[marketId] != address(0);
    }
}

