    }
    uint256 public totalShares; // WAD
    mapping(address => LpAccount) public lpAccounts;

    // ── Per-token liability ───────────────────────────────────────────────

    mapping(bytes32 => int256) public tokenLiabilities; // tokenKey => WAD

    // ── Settlement (pull-based, real-world price) ────────────────────────

    int256 public finalPrice;
    bool public marketResolved;
    /// @notice Scheduled close (unix seconds): earliest time any resolution path
    ///         may be invoked. Fixed at creation.
    uint256 public immutable resolvesAt;

    // ── DAO staking resolution (Phase 4B, non-price markets) ─────────────
    // The old owner-only two-phase timelock is replaced by a stake-weighted
    // optimistic oracle: a bonded proposal opens a dispute window; a challenger
    // counter-bonds an alternative price; token holders vote stake-weighted; the
    // losing side is slashed to the winners.

    int256 public proposedFinalPrice; // the proposer's asserted price (UPHOLD side)
    uint256 public resolutionTime; // 0 = no active proposal; else dispute-window deadline (unix sec)
    address public proposer;
    uint256 public proposerBond;
    bool public disputed;
    address public disputer;
    int256 public disputedFinalPrice; // the disputer's alternative price (REJECT side)
    uint256 public totalUphold; // HGOV staked on the proposer's price
    uint256 public totalReject; // HGOV staked on the disputer's price
    bool public upholdWon; // set at execution when disputed
    uint256 public winningPot; // total winning-side stake at execution
    uint256 public losingPot; // total slashed losing-side stake at execution
    mapping(address => uint256) public stakeUphold;
    mapping(address => uint256) public stakeReject;
    mapping(address => bool) public stakeClaimed;

    /// @notice Chainlink price feed (Phase 4A). `address(0)` = DAO-settled market;
    ///         a feed-bound market settles trustlessly, never via the DAO/owner.
    address public immutable priceFeed;

    // ── Events (mirror the Move events) ──────────────────────────────────

    event CurveUpdated(uint256 indexed marketId, int256 mu, int256 sigma);
    event LiquidityAdded(uint256 indexed marketId, address indexed provider, uint256 amountWad);
    event LiquidityRemoved(uint256 indexed marketId, address indexed provider, uint256 amountWad);
    event TradeExecuted(
        uint256 indexed marketId,
        address indexed user,
        bytes32 tokenKey,
        bool isYes,
        uint256 tokensMinted,
        int256 strike
    );
    event FeeDistributed(uint256 indexed marketId, uint256 amountWad);
    event MarketResolved(uint256 indexed marketId, int256 finalPrice);
    event WinningsClaimed(uint256 indexed marketId, address indexed user, uint256 amountWad);
    event ResolutionProposed(uint256 indexed marketId, address indexed proposer, int256 price, uint256 bond);
    event ResolutionDisputed(uint256 indexed marketId, address indexed disputer, int256 price, uint256 bond);
    event ResolutionVoted(uint256 indexed marketId, address indexed voter, bool support, uint256 amount);
    event StakeClaimed(uint256 indexed marketId, address indexed staker, uint256 amount);
    event OwnershipTransferStarted(address indexed previousOwner, address indexed newOwner);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    // ── Errors (mirror the Move E* abort codes) ──────────────────────────

    error Unauthorized(); // EUnauthorized
    error TradesStarted(); // ETradesStarted
    error VarianceTooLow(); // EVarianceTooLow
    error ZeroAmount(); // EZeroAmount
    error UnsupportedCollateralDecimals(uint8 decimals); // collateral has >18 decimals
    error ZeroAddress(); // EZeroAddress — addLiquidityFor beneficiary is the zero address
    error PriceZero(); // EPriceZero
    error ZeroTokens(); // EZeroTokens
    error InsufficientLiquidity(); // EInsufficientLiquidity
    error InsufficientShares(); // EInsufficientShares
    error NotResolved(); // ENotResolved
    error AlreadyResolved(); // EAlreadyResolved
    error NotWinner(); // ENotWinner
    error NoTokens(); // ENoTokens
    error WrongMarket(); // EWrongMarket
    error PositionWinning(); // EPositionWinning
    error NonPositiveWeight(); // ENonPositiveWeight
    error AlreadyProposed(); // EAlreadyProposed
    error NoProposal(); // ENoProposal
    error TimelockActive(); // ETimelockActive
    error MarketNotClosed(); // EMarketNotClosed
    error MarketClosed(); // EMarketClosed
    error FeedBoundMarket(); // EFeedBoundMarket
    error NoPriceFeed(); // ENoPriceFeed — resolveWithChainlink on a manual market
    error StalePrice(); // EStalePrice — Chainlink answer older than MAX_PRICE_AGE_SECS
    error BondTooLow(); // EBondTooLow — dispute bond below the proposer's bond
    error AlreadyDisputed(); // EAlreadyDisputed — a dispute is already open
    error NotDisputed(); // ENotDisputed — vote before a dispute exists
    error WindowClosed(); // EWindowClosed — propose/dispute/vote after the window
    error NothingToClaim(); // ENothingToClaim — no winning stake for the caller
    error AlreadyClaimed(); // EAlreadyClaimed — stake already withdrawn

    modifier onlyOwner() {
        if (msg.sender != owner) revert Unauthorized();
        _;
    }

    // ── Constructor (Move `create_market` body) ──────────────────────────

    /// @param _owner Market owner (the creator; passed through by the factory).
    /// @param _collateralToken ERC-20 used as collateral; any token with ≤18
    ///        decimals (typically 6-decimal USDC). Its decimals are read here to
    ///        derive the token↔WAD `collateralScale`.
    /// @param _positionNFT Shared `Position` ERC-721.
    /// @param _title Human-readable market title.
    /// @param _sigmaMinMag σ floor (WAD, non-negative).
    /// @param _resolvesAt Scheduled close (unix seconds, must be > 0).
    /// @param _priceFeed Chainlink feed, or `address(0)` for a manual market.
    /// @param _marketId Registry-assigned market id.
    constructor(
        address _owner,
        address _collateralToken,
        address _positionNFT,
        string memory _title,
        int256 _sigmaMinMag,
        uint256 _resolvesAt,
        address _priceFeed,
        uint256 _marketId
    ) {
        // Scheduled close is mandatory and fixed — it gates every resolution path.
        if (_resolvesAt == 0) revert MarketNotClosed();
        // The deployer is the factory (via `new HSKPredictMarket`); recorded so the
        // Chainlink path can read the protocol keeper from `factory.resolver()`.
        factory = msg.sender;
        owner = _owner;
        collateralToken = _collateralToken;
        // Derive the token↔WAD scale from the collateral's own decimals so any
        // ERC-20 (6-dec USDC, 18-dec CCIP-BnM, …) works. Internal accounting is
        // WAD (1e18); scale = 10 ** (18 - decimals).
        uint8 dec = IERC20Metadata(_collateralToken).decimals();
        if (dec > 18) revert UnsupportedCollateralDecimals(dec);
        collateralDecimals = dec;
        collateralScale = 10 ** (18 - dec);
        uint256 unit = 10 ** dec;
        dustMin = unit; // 1 collateral unit
        dustMax = 10 * unit; // 10 collateral units
        positionNFT = _positionNFT;
        title = _title;
        sigmaMin = _sigmaMinMag; // caller passes a non-negative magnitude
        resolvesAt = _resolvesAt;
        priceFeed = _priceFeed;
        marketId = _marketId;
        // mu/sigma start at 0; owner calls setDistribution before trading.
        priorWeight = DEFAULT_PRIOR_WEIGHT;
    }

    // ── Two-step ownership ────────────────────────────────────────────────

    /// @notice Begin transferring ownership; completes on `acceptOwnership`.
    function transferOwnership(address newOwner) external onlyOwner {
        pendingOwner = newOwner;
        emit OwnershipTransferStarted(owner, newOwner);
    }

    /// @notice Finalize an ownership transfer. Callable only by the pending owner.
    function acceptOwnership() external {
        if (msg.sender != pendingOwner) revert Unauthorized();
        emit OwnershipTransferred(owner, pendingOwner);
        owner = pendingOwner;
        pendingOwner = address(0);
    }

    // ── Owner configuration (pre-trading) ────────────────────────────────

    /// @notice Seed the prior μ/σ. Owner-only, before any trade. Seeds the
    ///         stake-weighted accumulators with `priorWeight` of virtual stake so
    ///         the first real bet can't yank the curve to a single point.
    function setDistribution(int256 muMag, bool muNeg, int256 sigmaMag) external onlyOwner {
        if (tradesStarted) revert TradesStarted();
        int256 s = sigmaMag; // non-negative magnitude
        if (s <= sigmaMin) revert VarianceTooLow();

        int256 m = _signed(muMag, muNeg);
        mu = m;
        sigma = s;

        int256 pw = priorWeight > 0 ? priorWeight : DEFAULT_PRIOR_WEIGHT;
        // E[x²] = μ² + σ², so reconstructing μ/σ from the accumulators is exact.
        int256 ex2 = m.mulWad(m) + s.mulWad(s);
        accStakeWeight = pw;
        accWeightedX = pw.mulWad(m);
        accWeightedXSq = pw.mulWad(ex2);

        emit CurveUpdated(marketId, mu, sigma);
    }

    /// @notice Tune how strongly the seeded μ/σ resists demand. Owner, pre-trading.
    function setPriorWeight(int256 weightMag) external onlyOwner {
        if (tradesStarted) revert TradesStarted();
        if (weightMag <= 0) revert NonPositiveWeight();
        priorWeight = weightMag;
    }

    /// @notice Update the σ floor. Owner-only, any time (matches Move; not gated on
    ///         `tradesStarted`) — applies on the next `recomputeCurve`.
    function setSigmaMin(int256 minMag) external onlyOwner {
        if (minMag <= 0) revert VarianceTooLow();
        sigmaMin = minMag;
    }

    // ── Liquidity ─────────────────────────────────────────────────────────

    /// @notice Deposit `amount` (USDC 6-dec units) and receive LP shares.
    ///         Curve-neutral: liquidity never moves μ/σ. Settles pending fees
    ///         first so the new share count doesn't dilute past rewards.
    function addLiquidity(uint256 amount) external nonReentrant {
        _addLiquidity(msg.sender, msg.sender, amount);
    }

    /// @notice Deposit `amount` collateral pulled from the caller and credit the
    ///         resulting LP shares to `beneficiary`. Enables **cross-chain
    ///         liquidity** (Phase 6): the CCIP receiver holds the bridged USDC and
    ///         calls this so the origin-chain depositor — not the bridge contract —
    ///         becomes the LP. Curve-neutral, exactly like `addLiquidity`.
    function addLiquidityFor(address beneficiary, uint256 amount) external nonReentrant {
        if (beneficiary == address(0)) revert ZeroAddress();
        _addLiquidity(msg.sender, beneficiary, amount);
    }

    /// @dev Shared liquidity deposit. Pulls `amount` (USDC 6-dec units) from
    ///      `payer` and credits the LP shares to `beneficiary`. Settles the
    ///      beneficiary's pending fees first so the new shares don't dilute past
    ///      rewards.
    function _addLiquidity(address payer, address beneficiary, uint256 amount) internal {
        _claimFeesInternal(beneficiary);

        if (amount == 0) revert ZeroAmount();
        uint256 amountWad = amount * collateralScale;

        IERC20(collateralToken).safeTransferFrom(payer, address(this), amount);
        availableLiquidity += int256(amountWad);

        uint256 newShares = lpAccounts[beneficiary].shares + amountWad;
        totalShares += amountWad;
        lpAccounts[beneficiary] = LpAccount(newShares, _rewardDebtFor(newShares));

        emit LiquidityAdded(marketId, beneficiary, amountWad);
    }

    /// @notice Burn `sharesToRemove` (WAD) and withdraw the equivalent collateral.
    ///         Solvency-checked against free liquidity.
    function removeLiquidity(uint256 sharesToRemove) external nonReentrant {
        address user = msg.sender;
        _claimFeesInternal(user);

        int256 sharesFp = int256(sharesToRemove);
        if (availableLiquidity < sharesFp) revert InsufficientLiquidity();

        uint256 cur = lpAccounts[user].shares;
        if (cur < sharesToRemove) revert InsufficientShares();
        uint256 newShares = cur - sharesToRemove;

        totalShares -= sharesToRemove;
        availableLiquidity -= sharesFp;
        lpAccounts[user] = LpAccount(newShares, _rewardDebtFor(newShares));

        uint256 units = sharesToRemove / collateralScale;
        if (units > 0) {
            IERC20(collateralToken).safeTransfer(user, units);
        }
        emit LiquidityRemoved(marketId, user, sharesToRemove);
    }

    /// @notice Claim accumulated trading fees for the caller.
    function claimFees() external nonReentrant {
        _claimFeesInternal(msg.sender);
    }

    // ── Trading ───────────────────────────────────────────────────────────

    /// @notice Buy a YES position (wins iff finalPrice ≥ strike). `paymentAmount`
    ///         is the full stake in USDC units; 1% fee to LPs, rest underwrites the
    ///         position and folds into the demand-weighted curve.
    function buyYes(
        uint256 paymentAmount,
        int256 targetMag,
        bool targetNeg
    ) external nonReentrant returns (uint256 tokenId) {
        return _buyInternal(paymentAmount, _signed(targetMag, targetNeg), true);
    }

    /// @notice Buy a NO position (wins iff finalPrice < strike).
    function buyNo(
        uint256 paymentAmount,
        int256 targetMag,
        bool targetNeg
    ) external nonReentrant returns (uint256 tokenId) {
        return _buyInternal(paymentAmount, _signed(targetMag, targetNeg), false);
    }

    function _buyInternal(
        uint256 paymentAmount,
        int256 target,
        bool isYes
    ) internal returns (uint256 tokenId) {
        // Trading closes at resolution and at the scheduled close. Without this,
        // once resolved (finalPrice public) anyone could buy a guaranteed-winning
        // strike priced below 1.0 and immediately claim a multiple of their stake.
        if (marketResolved) revert AlreadyResolved();
        if (block.timestamp >= resolvesAt) revert MarketClosed();
        if (paymentAmount == 0) revert ZeroAmount();

        // Price against the *pre-update* curve (μ/σ before this bet shifts them).
        int256 pNo = Gaussian.normalCdf(target, mu, sigma);
        int256 price = isYes ? WAD - pNo : pNo;
        uint256 priceMag = price.toUint256();
        if (priceMag == 0) revert PriceZero();

        uint256 stakeWad = paymentAmount * collateralScale;
        uint256 feeWad = stakeWad / 100; // 1% fee
        uint256 netWad = stakeWad - feeWad;
        uint256 tokensWad = (netWad * uint256(WAD)) / priceMag;
        if (tokensWad == 0) revert ZeroTokens();

        bytes32 tokenKey = _deriveTokenKey(target, isYes);

        // Custody the full stake, distribute the fee, lock the liability, and fold
        // the bet into the curve (weight = net stake, x = strike).
        IERC20(collateralToken).safeTransferFrom(msg.sender, address(this), paymentAmount);
        _distributeFee(feeWad);
        _underwrite(tokenKey, target, netWad, tokensWad);

        tokenId = Position(positionNFT).mint(msg.sender, target, isYes, tokensWad);

        emit TradeExecuted(marketId, msg.sender, tokenKey, isYes, tokensWad, target);
    }

    // ── Settlement (pull-based, against the real world) ──────────────────

    /// @notice Owner records the externally-observed final price. Single-shot, and
    ///         only once `resolvesAt` has passed. Users then claim per position.
    function setFinalPrice(int256 priceMag, bool priceNeg) external onlyOwner {
        if (marketResolved) revert AlreadyResolved();
        // A feed-bound market must settle trustlessly (Phase 4 Chainlink path);
        // the owner cannot override a bound source with an arbitrary manual price.
        if (priceFeed != address(0)) revert FeedBoundMarket();
        if (block.timestamp < resolvesAt) revert MarketNotClosed();
        finalPrice = _signed(priceMag, priceNeg);
        marketResolved = true;
        emit MarketResolved(marketId, finalPrice);
    }

    // ── DAO staking resolution (Phase 4B, non-price markets) ─────────────

    /// @dev The shared HGOV stake token, read from the deploying factory.
    function _gov() internal view returns (address) {
        return IProtocolRegistry(factory).govToken();
    }

    /// @notice DAO phase 1 — **permissionless but bonded**: assert the final price
    ///         by staking `MIN_PROPOSAL_BOND` HGOV, opening the dispute window.
    ///         Only for non-feed markets, after close. Replaces the owner-only
    ///         two-phase path — anyone may propose, but capital is at risk.
    function proposeResolution(int256 priceMag, bool priceNeg) external nonReentrant {
        if (marketResolved) revert AlreadyResolved();
        if (priceFeed != address(0)) revert FeedBoundMarket();
        if (resolutionTime != 0) revert AlreadyProposed();
        if (block.timestamp < resolvesAt) revert MarketNotClosed();

        IERC20(_gov()).safeTransferFrom(msg.sender, address(this), MIN_PROPOSAL_BOND);
        proposer = msg.sender;
        proposerBond = MIN_PROPOSAL_BOND;
        proposedFinalPrice = _signed(priceMag, priceNeg);
        resolutionTime = block.timestamp + DISPUTE_WINDOW;
        stakeUphold[msg.sender] += MIN_PROPOSAL_BOND;
        totalUphold += MIN_PROPOSAL_BOND;
        emit ResolutionProposed(marketId, msg.sender, proposedFinalPrice, MIN_PROPOSAL_BOND);
    }

    /// @notice DAO phase 2 — challenge the proposal by counter-bonding (`bond >=`
    ///         the proposer's bond) an alternative price, escalating to a
    ///         stake-weighted vote. One dispute per proposal; during the window.
    function disputeResolution(
        int256 counterMag,
        bool counterNeg,
        uint256 bond
    ) external nonReentrant {
        if (marketResolved) revert AlreadyResolved();
        if (resolutionTime == 0) revert NoProposal();
        if (block.timestamp >= resolutionTime) revert WindowClosed();
        if (disputed) revert AlreadyDisputed();
        if (bond < proposerBond) revert BondTooLow();

        IERC20(_gov()).safeTransferFrom(msg.sender, address(this), bond);
        disputed = true;
        disputer = msg.sender;
        disputedFinalPrice = _signed(counterMag, counterNeg);
        stakeReject[msg.sender] += bond;
        totalReject += bond;
        emit ResolutionDisputed(marketId, msg.sender, disputedFinalPrice, bond);
    }

    /// @notice DAO phase 3 — add stake-weighted conviction to a disputed proposal.
    ///         `support = true` backs the proposer's price (UPHOLD), `false` the
    ///         disputer's (REJECT). Only while disputed and within the window.
    function voteResolution(bool support, uint256 amount) external nonReentrant {
        if (marketResolved) revert AlreadyResolved();
        if (!disputed) revert NotDisputed();
        if (block.timestamp >= resolutionTime) revert WindowClosed();
        if (amount == 0) revert ZeroAmount();

        IERC20(_gov()).safeTransferFrom(msg.sender, address(this), amount);
        if (support) {
            stakeUphold[msg.sender] += amount;
            totalUphold += amount;
        } else {
            stakeReject[msg.sender] += amount;
            totalReject += amount;
        }
        emit ResolutionVoted(marketId, msg.sender, support, amount);
    }

    /// @notice DAO phase 4 — **permissionless finalize** after the window. An
    ///         undisputed proposal settles at the proposer's price; a disputed one
    ///         settles at the higher-staked side's price (tie → uphold). Slashing
    ///         is realized in `claimStake`. The backend keeper calls this to nudge
    ///         finalization once the window elapses.
    function executeResolution() external {
        if (marketResolved) revert AlreadyResolved();
        if (resolutionTime == 0) revert NoProposal();
        if (block.timestamp < resolutionTime) revert TimelockActive();

        if (!disputed) {
            upholdWon = true;
            winningPot = totalUphold;
            losingPot = 0;
            finalPrice = proposedFinalPrice;
        } else {
            bool uphold = totalUphold >= totalReject; // tie → uphold
            upholdWon = uphold;
            winningPot = uphold ? totalUphold : totalReject;
            losingPot = uphold ? totalReject : totalUphold;
            finalPrice = uphold ? proposedFinalPrice : disputedFinalPrice;
        }
        marketResolved = true;
        emit MarketResolved(marketId, finalPrice);
    }

    /// @notice DAO phase 5 — withdraw the caller's winning-side stake plus a
    ///         pro-rata share of the slashed losing stake. Losing-side stake is
    ///         forfeited. Callable once per address after resolution.
    function claimStake() external nonReentrant {
        if (!marketResolved) revert NotResolved();
        if (resolutionTime == 0) revert NoProposal(); // not a DAO-settled market
        if (stakeClaimed[msg.sender]) revert AlreadyClaimed();

        uint256 w = upholdWon ? stakeUphold[msg.sender] : stakeReject[msg.sender];
        if (w == 0) revert NothingToClaim();

        stakeClaimed[msg.sender] = true;
        // principal + pro-rata slice of the slashed losing pot.
        uint256 payout = w + (losingPot == 0 ? 0 : (w * losingPot) / winningPot);
        IERC20(_gov()).safeTransfer(msg.sender, payout);
        emit StakeClaimed(marketId, msg.sender, payout);
    }

    /// @notice Phase 4A — trustless settlement of a feed-bound (price) market from
    ///         its Chainlink aggregator. **Keeper-only, not permissionless**: only
    ///         the protocol resolver (`factory.resolver()`) may call it, so no
    ///         arbitrary account can trigger resolution. The backend keeper invokes
    ///         it automatically once the scheduled close is reached; a feed-bound
    ///         market has no dispute window (its price *is* the outcome). Writes the
    ///         same `finalPrice` / `MarketResolved` the other paths do — per-position
    ///         `claimWinnings` / `releaseLosingCollateral` are unchanged.
    function resolveWithChainlink() external {
        if (msg.sender != IProtocolRegistry(factory).resolver()) revert Unauthorized();
        if (marketResolved) revert AlreadyResolved();
        if (priceFeed == address(0)) revert NoPriceFeed();
        if (block.timestamp < resolvesAt) revert MarketNotClosed();

        (, int256 answer, , uint256 updatedAt, ) = AggregatorV3Interface(priceFeed).latestRoundData();
        if (answer <= 0) revert PriceZero();
        if (block.timestamp - updatedAt > MAX_PRICE_AGE_SECS) revert StalePrice();

        // Chainlink answers carry the feed's own decimals (USD feeds are 8dp);
        // rescale to the protocol's 18-decimal WAD.
        uint8 dec = AggregatorV3Interface(priceFeed).decimals();
        finalPrice = dec <= 18
            ? answer * int256(10 ** (18 - uint256(dec)))
            : answer / int256(10 ** (uint256(dec) - 18));
        marketResolved = true;
        emit MarketResolved(marketId, finalPrice);
    }

    /// @notice Redeem a winning position for collateral (1 USDC per token). Burns
    ///         the `Position` NFT; caller must own it.
    function claimWinnings(uint256 positionTokenId) external nonReentrant {
        if (!marketResolved) revert NotResolved();

        Position pos = Position(positionNFT);
        if (pos.ownerOf(positionTokenId) != msg.sender) revert Unauthorized();
        Position.PositionData memory pd = pos.getPosition(positionTokenId);
        if (pd.market != address(this)) revert WrongMarket();

        bool won = pd.isYes ? finalPrice >= pd.strike : finalPrice < pd.strike;
        if (!won) revert NotWinner();
        if (pd.amountWad == 0) revert NoTokens();

        bytes32 tokenKey = _deriveTokenKey(pd.strike, pd.isYes);
        int256 amt = int256(pd.amountWad);
        _reduceLiability(tokenKey, amt);
        lockedCollateral -= amt;

        pos.burn(positionTokenId);

        uint256 units = pd.amountWad / collateralScale;
        if (units > 0) {
            IERC20(collateralToken).safeTransfer(msg.sender, units);
        }
        emit WinningsClaimed(marketId, msg.sender, pd.amountWad);
    }

    /// @notice Permissionless: free the collateral locked by a losing token id back
    ///         into available liquidity. Anyone may call after resolution.
    function releaseLosingCollateral(int256 targetMag, bool targetNeg, bool isYes) external {
        if (!marketResolved) revert NotResolved();
        int256 target = _signed(targetMag, targetNeg);
        bool won = isYes ? finalPrice >= target : finalPrice < target;
        if (won) revert PositionWinning();

        bytes32 tokenKey = _deriveTokenKey(target, isYes);
        int256 liab = tokenLiabilities[tokenKey];
        if (liab != 0) {
            tokenLiabilities[tokenKey] = 0;
            lockedCollateral -= liab;
            availableLiquidity += liab;
        }
    }

    /// @notice Owner recovers USDC rounding dust (vault balance beyond accounted
    ///         liquidity). Capped at 10 USDC and floored above 1 USDC.
    function sweepDust() external onlyOwner nonReentrant {
        int256 expectedWad = availableLiquidity + lockedCollateral;
        if (expectedWad < 0) return;
        uint256 expectedUnits = uint256(expectedWad) / collateralScale;

        uint256 actual = IERC20(collateralToken).balanceOf(address(this));
        if (actual > expectedUnits) {
            uint256 dust = actual - expectedUnits;
            if (dust > dustMin && dust <= dustMax) {
                IERC20(collateralToken).safeTransfer(owner, dust);
            }
        }
    }

    // ── Internal: fees / curve / liabilities ─────────────────────────────

    function _distributeFee(uint256 feeWad) internal {
        if (totalShares > 0) {
            int256 inc = int256((feeWad * uint256(WAD)) / totalShares);
            accFeePerShare += inc;
            availableLiquidity += int256(feeWad);
            emit FeeDistributed(marketId, feeWad);
        }
    }

    function _claimFeesInternal(address user) internal {
        uint256 shares = lpAccounts[user].shares;
        if (shares == 0) return;

        int256 total = _rewardDebtFor(shares);
        int256 pending = total - lpAccounts[user].rewardDebt;
        if (pending > 0) {
            availableLiquidity -= pending;
            lpAccounts[user].rewardDebt = total;

            uint256 units = uint256(pending) / collateralScale;
            if (units > 0) {
                IERC20(collateralToken).safeTransfer(user, units);
            }
        }
    }

    /// @dev Lock collateral for a bet and fold it into the stake-weighted curve.
    ///      Only bets reach this path — liquidity never does — which is exactly why
    ///      LP deposits cannot move μ/σ.
    function _underwrite(bytes32 tokenKey, int256 target, uint256 premiumWad, uint256 liabilityWad) internal {
        tradesStarted = true;

        int256 premium = int256(premiumWad);
        int256 liability = int256(liabilityWad);
        if (availableLiquidity < liability) revert InsufficientLiquidity();

        availableLiquidity = availableLiquidity + premium - liability;
        lockedCollateral += liability;
        tokenLiabilities[tokenKey] += liability;

        // Curve accumulators: weight = net stake, x = strike.
        int256 xSq = target.mulWad(target);
        accStakeWeight += premium;
        accWeightedX += premium.mulWad(target);
        accWeightedXSq += premium.mulWad(xSq);
        _recomputeCurve();
    }

    /// @dev μ = Σwx/Σw, σ = sqrt(E[x²] − μ²), floored at sigmaMin.
    function _recomputeCurve() internal {
        int256 tw = accStakeWeight;
        if (tw <= 0) return;

        int256 m = accWeightedX.divWad(tw);
        int256 ex2 = accWeightedXSq.divWad(tw);
        int256 variance = ex2 - m.mulWad(m);

        int256 s = variance > 0 ? Gaussian.sqrtWad(variance) : int256(0);
        if (s < sigmaMin) s = sigmaMin;

        mu = m;
        sigma = s;
        emit CurveUpdated(marketId, mu, sigma);
    }

    function _reduceLiability(bytes32 tokenKey, int256 amt) internal {
        int256 cur = tokenLiabilities[tokenKey];
        if (cur < amt) revert InsufficientLiquidity();
        tokenLiabilities[tokenKey] = cur - amt;
    }

    /// @dev MasterChef reward-debt for a share balance: shares·accFeePerShare/WAD.
    ///      `accFeePerShare` is always non-negative.
    function _rewardDebtFor(uint256 shares) internal view returns (int256) {
        return int256((shares * uint256(accFeePerShare)) / uint256(WAD));
    }

    // ── Internal: token key / sign helpers ───────────────────────────────

    /// @dev keccak256(marketId, strikeMag, strikeNeg, isYes). Only needs to be
    ///      internally consistent for liability tracking (matches the Move
    ///      `derive_token_id` structure with EVM-native encoding).
    function _deriveTokenKey(int256 target, bool isYes) internal view returns (bytes32) {
        uint256 mag = uint256(target.abs());
        bool neg = target < 0;
        return keccak256(abi.encodePacked(marketId, mag, neg, isYes));
    }

    /// @dev Reattach a sign to a non-negative magnitude (mirrors `fp::from`).
    function _signed(int256 mag, bool neg) internal pure returns (int256) {
        return neg ? -mag : mag;
    }

    // ── Views ─────────────────────────────────────────────────────────────

    /// @notice Current μ (signed WAD).
    function getMu() external view returns (int256) {
        return mu;
    }

    /// @notice Current σ (WAD, non-negative).
    function getSigma() external view returns (int256) {
        return sigma;
    }

    /// @notice CDF-derived price (WAD) for a strike/direction, against the live
    ///         curve.
    function getPrice(int256 targetMag, bool targetNeg, bool isYes) external view returns (uint256) {
        int256 target = _signed(targetMag, targetNeg);
        int256 cdf = Gaussian.normalCdf(target, mu, sigma);
        int256 p = isYes ? WAD - cdf : cdf;
        return p.toUint256();
    }

    function isResolved() external view returns (bool) {
        return marketResolved;
    }

    /// @notice LP share balance for a provider (WAD).
    function lpBalance(address user) external view returns (uint256) {
        return lpAccounts[user].shares;
    }

    /// @notice Unclaimed trading fees for an LP (WAD): shares·acc/WAD − rewardDebt.
    function pendingFees(address user) external view returns (uint256) {
        uint256 shares = lpAccounts[user].shares;
        if (shares == 0) return 0;
        uint256 total = (shares * uint256(accFeePerShare)) / uint256(WAD);
        uint256 rd = uint256(lpAccounts[user].rewardDebt); // non-negative
        return total > rd ? total - rd : 0;
    }

    /// @notice Derive the token key for a (strike, direction).
    function computeTokenKey(int256 targetMag, bool targetNeg, bool isYes) external view returns (bytes32) {
        return _deriveTokenKey(_signed(targetMag, targetNeg), isYes);
    }

    /// @notice Collateral held by the vault (USDC units).
    function vaultValue() external view returns (uint256) {
        return IERC20(collateralToken).balanceOf(address(this));
    }
}

