pragma solidity ^0.8.24;

import {ERC721} from "@openzeppelin/contracts/token/ERC721/ERC721.sol";

/// @title Position
/// @notice ERC-721 representing a single YES/NO bet in a HSKPredict market.
/// @dev Solidity port of the Sui Move owned `Position` object (`market.move`).
///
///      On Sui a `Position` is a first-class owned object minted to the buyer and
///      consumed by `claim_winnings`. On EVM that becomes an ERC-721 NFT: the
///      market mints one on every `buyYes`/`buyNo` and burns it on
///      `claimWinnings`. Native ERC-721 transferability replaces the Move
///      `position_market` Kiosk secondary market — a position is tradeable on any
///      NFT marketplace with no extra contract.
///
///      A single `Position` contract is shared by every market (deployed by
///      `HSKPredictFactory`); each market is authorized once at creation and is the
///      only address allowed to mint/burn its positions.
contract Position is ERC721 {
    /// @notice On-chain data for a bet. Mirrors the Move `Position` fields
    ///         (`market_id`/`token_id` collapse to the market address + the
    ///         market-side liability key, which is recomputed from these fields).
    struct PositionData {
        address market; // the HSKPredictMarket that minted this position
        int256 strike; // WAD — the strike price the bet was opened at
        bool isYes; // YES (wins iff finalPrice >= strike) or NO (wins iff <)
        uint256 amountWad; // tokens held (WAD); pays 1 USDC / token if it wins
    }

    /// @dev Auto-incrementing token id counter.
    uint256 private _nextTokenId;

    /// @notice Per-token bet data.
    mapping(uint256 => PositionData) public positions;

    /// @notice Markets allowed to mint/burn positions (authorized by the factory).
    mapping(address => bool) public authorizedMarkets;

    /// @notice The factory that deployed this contract; the sole authorizer.
    address public immutable factory;

    error NotAuthorized();
    error OnlyFactory();
    error WrongMarket();

    modifier onlyAuthorized() {
        if (!authorizedMarkets[msg.sender]) revert NotAuthorized();
        _;
    }

    constructor(address _factory) ERC721("HSK Predict Position", "HPOS") {
        factory = _factory;
    }

    /// @notice Authorize a market to mint/burn positions. Factory-only; called
    ///         once per market at creation time.
    function authorizeMarket(address market) external {
        if (msg.sender != factory) revert OnlyFactory();
        authorizedMarkets[market] = true;
    }

    /// @notice Mint a new position to `to`. Authorized markets only.
    /// @dev The position's `market` binding is forced to `msg.sender` (the calling
    ///      authorized market) — it is never caller-supplied, so a market can only
    ///      ever mint positions bound to itself.
    /// @return tokenId The freshly minted ERC-721 id.
    function mint(
        address to,
        int256 strike,
        bool isYes,
        uint256 amountWad
    ) external onlyAuthorized returns (uint256 tokenId) {
        tokenId = _nextTokenId++;
        positions[tokenId] = PositionData(msg.sender, strike, isYes, amountWad);
        _mint(to, tokenId);
    }

    /// @notice Burn a position (on winning-claim). Only the market that owns the
    ///         position (its `market` binding) may burn it, so one authorized
    ///         market can never burn another market's token.
    function burn(uint256 tokenId) external onlyAuthorized {
        if (positions[tokenId].market != msg.sender) revert WrongMarket();
        _burn(tokenId);
        delete positions[tokenId];
    }

    /// @notice Full struct read (public mapping getter returns a tuple; this
    ///         returns the struct for callers that want it typed).
    function getPosition(uint256 tokenId) external view returns (PositionData memory) {
        return positions[tokenId];
    }
}

