pragma solidity ^0.8.24;

/// @title FixedPoint
/// @notice Signed WAD (1e18) fixed-point arithmetic over `int256`.
/// @dev Solidity port of `continuum::fixed_point` (Move). The Move version had to
///      carry a magnitude/sign `Fp { mag, neg }` struct because Sui Move has no
///      native signed integer. Solidity has `int256`, so the sign is native and
///      the struct disappears — every value below is simply a WAD-scaled `int256`
///      (the real number `v` is stored as `v * 1e18`).
///
///      Parity note: Move performed division on the unsigned magnitude (truncating
///      toward zero) and reattached the sign afterwards. Solidity's `int256`
///      division also truncates toward zero, so `mulWad`/`divWad`/`divInt` produce
///      bit-identical results to the Move implementation.
library FixedPoint {
    /// @notice WAD scaling factor: 1e18.
    int256 internal constant WAD = 1e18;

    /// @notice One half in WAD (0.5).
    int256 internal constant HALF_WAD = 5e17;

    /// @dev Attempted to read a negative value as an unsigned magnitude.
    error NegativeToUnsigned();

    /// @notice WAD multiply: (a * b) / 1e18, truncating toward zero.
    function mulWad(int256 a, int256 b) internal pure returns (int256) {
        return (a * b) / WAD;
    }

    /// @notice WAD divide: (a * 1e18) / b, truncating toward zero.
    /// @dev Division by zero yields 0, matching the Move `div` guard.
    function divWad(int256 a, int256 b) internal pure returns (int256) {
        if (b == 0) return 0;
        return (a * WAD) / b;
    }

    /// @notice Divide by a plain integer, preserving sign.
    /// @dev Mirrors Move `div_int`; used by the exp/CDF series which divide by the
    ///      term index `n` and by 2. Division by zero yields 0.
    function divInt(int256 a, int256 n) internal pure returns (int256) {
        if (n == 0) return 0;
        return a / n;
    }

    /// @notice Absolute value.
    function abs(int256 a) internal pure returns (int256) {
        return a >= 0 ? a : -a;
    }

    /// @notice Read a non-negative value as `uint256`, reverting if negative.
    function toUint256(int256 a) internal pure returns (uint256) {
        if (a < 0) revert NegativeToUnsigned();
        return uint256(a);
    }
}

