pragma solidity ^0.8.24;

import {FixedPoint} from "./FixedPoint.sol";

/// @title Gaussian
/// @notice On-chain Gaussian math: PDF, CDF, error function and their helpers.
/// @dev Direct port of `continuum::gaussian` (Move), itself a port of the Stylus
///      `math_core.rs`:
///        - `erf` via the Abramowitz & Stegun 5-coefficient polynomial (formula
///          7.1.26, max error ~1.5e-7)
///        - `exp` via an 18-term Taylor series, clamped to [-20, +20] WAD
///        - WAD integer `sqrt` via Newton's method
///      All values are signed WAD fixed-point (`int256`, 1e18 scale). The Move
///      `Fp` struct collapses to native `int256`; every arithmetic step maps
///      one-to-one, so outputs match the Move implementation exactly.
library Gaussian {
    using FixedPoint for int256;

    /// @dev WAD scaling factor: 1e18.
    int256 private constant WAD = 1e18;

    // Abramowitz & Stegun erf coefficients (WAD-scaled). a2 and a4 are negative.
    int256 private constant ERF_P = 327_591_100_000_000_000; //  0.3275911
    int256 private constant ERF_A1 = 254_829_592_000_000_000; //  0.254829592
    int256 private constant ERF_A2 = -284_496_736_000_000_000; // -0.284496736
    int256 private constant ERF_A3 = 1_421_413_741_000_000_000; //  1.421413741
    int256 private constant ERF_A4 = -1_453_152_027_000_000_000; // -1.453152027
    int256 private constant ERF_A5 = 1_061_405_429_000_000_000; //  1.061405429

    /// @dev 0.5 in WAD.
    int256 private constant HALF_WAD = 5e17;
    /// @dev √2 in WAD.
    int256 private constant SQRT2 = 1_414_213_562_373_095_048;
    /// @dev √(2π) in WAD.
    int256 private constant SQRT_2PI = 2_506_628_274_631_000_502;

    /// @dev exp clamp bounds and the saturating output above +20.
    int256 private constant MAX_EXP = 20e18; //  20.0
    int256 private constant MIN_EXP = -20e18; // -20.0
    int256 private constant EXP_SAT = 1e26; // ~e^20 saturation ceiling

    /// @notice Clamp a value into the unit interval [0, 1 WAD].
    function clampUnit(int256 x) internal pure returns (int256) {
        if (x < 0) return 0;
        if (x > WAD) return WAD;
        return x;
    }

    /// @notice e^x in WAD.
    /// @dev Saturates to ~1e26 above +20 and underflows to 0 below -20, matching
    ///      the Stylus/Move guards that keep the series from overflowing.
    function expWad(int256 x) internal pure returns (int256) {
        if (x >= MAX_EXP) return EXP_SAT;
        if (x <= MIN_EXP) return 0;

        int256 term = WAD;
        int256 sum = WAD;
        for (int256 n = 1; n <= 18; ++n) {
            term = term.mulWad(x);
            term = term.divInt(n);
            sum += term;
        }
        return sum < 0 ? int256(0) : sum;
    }

    /// @notice Abramowitz & Stegun erf approximation (max error ~1.5e-7).
    function erf(int256 x) internal pure returns (int256) {
        if (x == 0) return 0;
        bool signNeg = x < 0;
        int256 ax = x.abs();

        int256 t = WAD.divWad(WAD + ERF_P.mulWad(ax));
        int256 t2 = t.mulWad(t);
        int256 t3 = t2.mulWad(t);
        int256 t4 = t3.mulWad(t);
        int256 t5 = t4.mulWad(t);

        int256 poly = ERF_A1.mulWad(t) +
            ERF_A2.mulWad(t2) +
            ERF_A3.mulWad(t3) +
            ERF_A4.mulWad(t4) +
            ERF_A5.mulWad(t5);

        int256 expTerm = expWad(-ax.mulWad(ax));
        int256 result = clampUnit(WAD - poly.mulWad(expTerm));

        return signNeg ? -result : result;
    }

    /// @notice CDF of N(mu, sigma) at x, i.e. Φ((x - μ)/σ). Returns [0, 1 WAD].
    /// @dev Non-positive sigma yields 0 (matches the Stylus/Move guard).
    function normalCdf(
        int256 x,
        int256 mu,
        int256 sigma
    ) internal pure returns (int256) {
        if (sigma <= 0) return 0;
        int256 z = (x - mu).divWad(sigma);
        int256 z2 = z.divWad(SQRT2); // / √2
        int256 e = erf(z2);
        int256 cdf = (WAD + e).divInt(2);
        return clampUnit(cdf);
    }

    /// @notice PDF of N(mu, sigma) at x. Returns [0, 1 WAD].
    /// @dev Included for parity with the Stylus/Move implementation; pricing only
    ///      needs `normalCdf`.
    function normalPdf(
        int256 x,
        int256 mu,
        int256 sigma
    ) internal pure returns (int256) {
        if (sigma <= 0) return 0;
        int256 z = (x - mu).divWad(sigma);
        int256 z2 = z.mulWad(z);
        int256 exponent = z2.mulWad(-HALF_WAD); // * -0.5
        int256 expVal = expWad(exponent);
        int256 denom = sigma.mulWad(SQRT_2PI); // σ·√(2π)
        if (denom == 0) return 0;
        int256 invDenom = WAD.divWad(denom);
        return clampUnit(invDenom.mulWad(expVal));
    }

    /// @notice Integer sqrt in WAD precision via Newton's method.
    /// @dev sqrt_wad(x_wad) = sqrt(x_wad * WAD) so the result stays WAD-scaled.
    ///      Negative or zero input returns zero. Operates on `uint256` internally,
    ///      exactly like the Move version's `u256` magnitude arithmetic.
    function sqrtWad(int256 x) internal pure returns (int256) {
        if (x <= 0) return 0;
        uint256 xm = uint256(x);
        uint256 scaled = xm * uint256(WAD);
        uint256 guess = scaled;
        if (xm > uint256(WAD)) {
            guess = xm;
        }

        for (uint256 i = 0; i < 128; ++i) {
            uint256 next = (guess + scaled / guess) / 2;
            if (next >= guess) break;
            guess = next;
        }
        return int256(guess);
    }
}
